// Generated by Tessa from plans/close-ticket/tests.json (run 20261016T080104Z).
// Story: Close and reopen a ticket
// Sessions come from stored storage state files; see README.md. No credentials are in this file.
import { expect, test } from '@playwright/test';

test.describe('Close and reopen a ticket', () => {
  test.describe('as editor', () => {
    // Signed-in session for editor; see README.md.
    test.use({ storageState: process.env.TESSA_AUTH_EDITOR ?? '.auth/editor.json' });

    test(
      'Editor closes an open ticket',
      {
        tag: ['@close-ticket', '@editor', '@happy-path'],
        annotation: [
          {
            type: 'intent',
            description:
              'Proves an editor can close an open ticket from its detail page and the status changes to closed.',
          },
          { type: 'seed-profile', description: 'default' },
          { type: 'criterion', description: 'ac-1' },
        ],
      },
      async ({ page }) => {
        await page.goto('/tickets/1');
        await test.step('Ticket #1 starts open', async () => {
          await expect(page.getByTestId('ticket-status')).toHaveText('open');
        });
        await test.step('Click Close ticket', async () => {
          await page.getByRole('button', { name: 'Close ticket' }).click();
        });
        await test.step('The status shows closed', async () => {
          await expect(page.getByTestId('ticket-status')).toHaveText('closed');
        });
      },
    );

    test(
      'Editor reopens a closed ticket',
      {
        tag: ['@close-ticket', '@editor', '@happy-path'],
        annotation: [
          {
            type: 'intent',
            description:
              'Proves an editor can reopen a closed ticket and the status changes back to open.',
          },
          { type: 'seed-profile', description: 'default' },
          { type: 'criterion', description: 'ac-2' },
        ],
      },
      async ({ page }) => {
        await page.goto('/tickets/3');
        await test.step('Ticket #3 starts closed', async () => {
          await expect(page.getByTestId('ticket-status')).toHaveText('closed');
        });
        await test.step('Click Reopen ticket', async () => {
          await page.getByRole('button', { name: 'Reopen ticket' }).click();
        });
        await test.step('The status shows open', async () => {
          await expect(page.getByTestId('ticket-status')).toHaveText('open');
        });
      },
    );

    test(
      'A closed ticket moves from the open filter to the closed filter',
      {
        tag: ['@close-ticket', '@editor', '@edge'],
        annotation: [
          {
            type: 'intent',
            description:
              "Proves the ticket list's status filter reflects a ticket that was just closed.",
          },
          { type: 'seed-profile', description: 'default' },
          { type: 'criterion', description: 'ac-3' },
        ],
      },
      async ({ page }) => {
        await page.goto('/tickets/2');
        await test.step('Close ticket #2', async () => {
          await page.getByTestId('ticket-toggle-status').click();
        });
        await test.step('Wait for the status to show closed', async () => {
          await expect(page.getByTestId('ticket-status')).toHaveText('closed');
        });
        await test.step('Open the ticket list', async () => {
          await page.goto('/tickets');
        });
        await test.step('Filter to closed tickets', async () => {
          await page.getByTestId('status-filter').selectOption('closed');
        });
        await test.step('Ticket #2 is listed', async () => {
          await expect(page.getByTestId('ticket-row-2')).toBeVisible();
        });
        await test.step('Filter to open tickets', async () => {
          await page.getByTestId('status-filter').selectOption('open');
        });
        await test.step('Ticket #2 is not listed', async () => {
          await expect(page.getByTestId('ticket-row-2')).toHaveCount(0);
        });
      },
    );
  });

  test.describe('as viewer', () => {
    // Signed-in session for viewer; see README.md.
    test.use({ storageState: process.env.TESSA_AUTH_VIEWER ?? '.auth/viewer.json' });

    test(
      'Viewer sees a ticket but cannot close it',
      {
        tag: ['@close-ticket', '@viewer', '@permissions'],
        annotation: [
          {
            type: 'intent',
            description:
              "Proves a viewer can read a ticket's detail page but gets no close or reopen control.",
          },
          { type: 'seed-profile', description: 'default' },
          { type: 'criterion', description: 'ac-4' },
        ],
      },
      async ({ page }) => {
        await page.goto('/tickets/1');
        await test.step('The ticket detail is shown', async () => {
          await expect(page.getByTestId('ticket-detail')).toBeVisible();
        });
        await test.step('There is no close or reopen button', async () => {
          await expect(page.getByTestId('ticket-toggle-status')).toHaveCount(0);
        });
      },
    );
  });
});
